const rawLeadItems = $('Pull Lead Tracker Info').all();

const leadItems = [];
for (let i = 0; i < rawLeadItems.length; i++) {
  if (rawLeadItems[i].json.fields !== undefined) {
    leadItems.push(rawLeadItems[i]);
  }
}
const seenEmails = {};
const dedupedLeadItems = [];
let duplicateCount = 0;

for (let i = 0; i < leadItems.length; i++) {
  const email = leadItems[i].json.fields.email;

  if (seenEmails[email] === undefined) {
    seenEmails[email] = true;
    dedupedLeadItems.push(leadItems[i]);
  } else {
    duplicateCount = duplicateCount + 1;
  }
}

const cleanLeadItems = dedupedLeadItems;
// ---------- Pipeline Status ----------
const statusCounts = {};
let totalLeads = 0;

for (let i = 0; i < cleanLeadItems.length; i++) {
  const record = cleanLeadItems[i].json;
  const status = record.fields.status;

  totalLeads = totalLeads + 1;

  if (statusCounts[status] === undefined) {
    statusCounts[status] = 1;
  } else {
    statusCounts[status] = statusCounts[status] + 1;
  }
}

function getCount(statusName) {
  const count = statusCounts[statusName];
  if (count === undefined) {
    return 0;
  }
  return count;
}

const wonCount = getCount("Won");
const lostCount = getCount("Lost");
const openPipeline = totalLeads - wonCount - lostCount;

// ---------- Conversion Rates ----------
const repliedOrLaterStatuses = ["Replied", "Call Booked", "Proposal Sent", "Won", "Lost"];
const bookedOrLaterStatuses = ["Call Booked", "Proposal Sent", "Won", "Lost"];

let repliedOrLaterCount = 0;
let bookedOrLaterCount = 0;

for (let i = 0; i < cleanLeadItems.length; i++) {
  const record = cleanLeadItems[i].json;
  const status = record.fields.status;

  if (repliedOrLaterStatuses.includes(status)) {
    repliedOrLaterCount = repliedOrLaterCount + 1;
  }

  if (bookedOrLaterStatuses.includes(status)) {
    bookedOrLaterCount = bookedOrLaterCount + 1;
  }
}

let replyRate = 0;
if (totalLeads > 0) {
  replyRate = repliedOrLaterCount / totalLeads;
}

let bookingRate = 0;
if (repliedOrLaterCount > 0) {
  bookingRate = bookedOrLaterCount / repliedOrLaterCount;
}

let closeRate = 0;
const closedTotal = wonCount + lostCount;
if (closedTotal > 0) {
  closeRate = wonCount / closedTotal;
}

function toPercent(rate) {
  const percent = rate * 100;
  return percent.toFixed(1);
}

// ---------- Weekly Priorities ----------
function getDaysSince(dateString) {
  const pastDate = DateTime.fromISO(dateString);
  const now = DateTime.now();
  const diff = now.diff(pastDate, "days");
  return diff.days;
}

function getPriority(record) {
  const status = record.fields.status;
  const daysSinceUpdate = getDaysSince(record.fields.last_modified);

  if (status === "Proposal Sent" && daysSinceUpdate > 5) {
    return { level: "HIGH", reason: "Proposal going cold, follow up now" };
  }

  if (status === "Replied" && daysSinceUpdate > 2) {
    return { level: "MEDIUM", reason: "They replied, you haven't booked a call yet" };
  }

  if (status === "Sent" && daysSinceUpdate > 14) {
    return { level: "LOW", reason: "No response in 2 weeks, decide: second touch or drop" };
  }

  return null;
}

const priorityOrder = { HIGH: 1, MEDIUM: 2, LOW: 3 };
const priorityLeads = [];

for (let i = 0; i < leadItems.length; i++) {
  const record = leadItems[i].json;
  const priority = getPriority(record);

  if (priority !== null) {
    priorityLeads.push({
      firstName: record.fields.first_name,
      lastName: record.fields.last_name,
      companyName: record.fields.company_name,
      status: record.fields.status,
      priorityLevel: priority.level,
      reason: priority.reason
    });
  }
}

priorityLeads.sort(function (a, b) {
  return priorityOrder[a.priorityLevel] - priorityOrder[b.priorityLevel];
});

function getPriorityEmoji(level) {
  if (level === "HIGH") {
    return "🔴";
  }
  if (level === "MEDIUM") {
    return "🟠";
  }
  return "🟡";
}

let prioritiesText = "";

if (priorityLeads.length === 0) {
  prioritiesText = "<i>Nothing urgent, pipeline is healthy.</i>";
} else {
  for (let i = 0; i < priorityLeads.length; i++) {
    const lead = priorityLeads[i];
    const emoji = getPriorityEmoji(lead.priorityLevel);
    prioritiesText = prioritiesText + emoji + " <b>" + lead.firstName + " " + lead.lastName + "</b> (" + lead.companyName + ")\n<i>" + lead.reason + "</i>\n\n";
  }
}

// ---------- Build Message ----------
let duplicateWarning = "";
if (duplicateCount > 0) {
  duplicateWarning = "⚠️ <i>" + duplicateCount + " duplicate email(s) found, cleanup needed</i>\n\n";
}

const today = DateTime.now().toFormat("dd LLL yyyy");

const message =
  "<b>📊 Monday Digest — " + today + "</b>\n\n" +
  duplicateWarning +
  "<b>Pipeline Status</b>\n" +
  "🔵 Sent: <code>" + getCount("Sent") + "</code>\n" +
  "🟡 Replied: <code>" + getCount("Replied") + "</code>\n" +
  "🟢 Call Booked: <code>" + getCount("Call Booked") + "</code>\n" +
  "🟣 Proposal Sent: <code>" + getCount("Proposal Sent") + "</code>\n" +
  "✅ Won: <code>" + wonCount + "</code>\n" +
  "❌ Lost: <code>" + lostCount + "</code>\n\n" +
  "<b>📈 Open Pipeline:</b> <code>" + openPipeline + "</code> / <code>" + totalLeads + "</code> total\n\n" +
  "<b>Conversion Rates</b>\n" +
  "💬 Reply Rate: <b>" + toPercent(replyRate) + "%</b>\n" +
  "📅 Booking Rate: <b>" + toPercent(bookingRate) + "%</b>\n" +
  "🏆 Close Rate: <b>" + toPercent(closeRate) + "%</b>\n\n" +
  "<b>🎯 This Week's Priorities</b>\n" +
  prioritiesText;

return [
  {
    json: {
      message: message
    }
  }
];

return [
  {
    json: {
      message: message
    }
  }
];

function isLastMonth(dateString) {
  const itemDate = DateTime.fromISO(dateString);

  const startOfThisMonth = DateTime.now().startOf("month");
  const startOfLastMonth = startOfThisMonth.minus({ months: 1 });
  const endOfLastMonth = startOfThisMonth.minus({ days: 1 }).endOf("day");

  if (itemDate >= startOfLastMonth && itemDate <= endOfLastMonth) {
    return true;
  }

  return false;
}

const leadItems = $('Fetch Lead Tracker').all();
const timeItems = $('Fetch Time Table').all();

// ---------- Revenue ----------
let revenue = 0;

for (let i = 0; i < leadItems.length; i++) {
  const record = leadItems[i].json;
  const status = record.fields.status;
  const wonDate = record.fields.last_modified;

  if (status === "Won" && isLastMonth(wonDate)) {
    const leadRevenue = record.fields.revenue;
    if (leadRevenue !== undefined) {
      revenue = revenue + leadRevenue;
    }
  }
}

// ---------- Hours Worked ----------
let hoursWorked = 0;

for (let i = 0; i < timeItems.length; i++) {
  const record = timeItems[i].json;
  const entryDate = record.fields.date;

  if (isLastMonth(entryDate)) {
    const hours = record.fields.hours;
    if (hours !== undefined) {
      hoursWorked = hoursWorked + hours;
    }
  }
}

// ---------- Effective Hourly Rate ----------
let effectiveHourlyRate = 0;

if (hoursWorked > 0) {
  effectiveHourlyRate = revenue / hoursWorked;
}

// ---------- Top Lead Source ----------
const revenueBySource = {};

for (let i = 0; i < leadItems.length; i++) {
  const record = leadItems[i].json;
  const status = record.fields.status;
  const wonDate = record.fields.last_modified;

  if (status === "Won" && isLastMonth(wonDate)) {
    const source = record.fields.lead_source;
    const leadRevenue = record.fields.revenue;

    if (leadRevenue !== undefined) {
      if (revenueBySource[source] === undefined) {
        revenueBySource[source] = leadRevenue;
      } else {
        revenueBySource[source] = revenueBySource[source] + leadRevenue;
      }
    }
  }
}

let topLeadSource = "None";
let topLeadSourceRevenue = 0;
const sourceNames = Object.keys(revenueBySource);

for (let i = 0; i < sourceNames.length; i++) {
  const source = sourceNames[i];
  const sourceRevenue = revenueBySource[source];

  if (sourceRevenue > topLeadSourceRevenue) {
    topLeadSourceRevenue = sourceRevenue;
    topLeadSource = source;
  }
}

// ---------- Build Message ----------
const monthName = DateTime.now().minus({ months: 1 }).toFormat("LLLL yyyy");

const message =
  "<b>🗓️ Monthly Report — " + monthName + "</b>\n\n" +
  "<b>💰 Revenue:</b> <code>€" + revenue + "</code>\n" +
  "<b>⏱️ Hours Worked:</b> <code>" + hoursWorked + "</code>\n" +
  "<b>⚡ Effective Hourly Rate:</b> <code>€" + effectiveHourlyRate.toFixed(2) + "/hr</code>\n" +
  "<b>🏆 Top Lead Source:</b> <i>" + topLeadSource + "</i> (€" + topLeadSourceRevenue + ")";

return [
  {
    json: {
      message: message
    }
  }
];
